946  struct morx
   947  {
   948    static const hb_tag_t tableTag = HB_AAT_TAG_morx;
   949
   950    inline bool has_data (void) const { return version != 0; }
   951
   952    inline void apply (hb_aat_apply_context_t *c) const
   953    {
   954      if (unlikely (!c->buffer->successful)) return;
   955      c->set_lookup_index (0);
   956      const Chain *chain = &firstChain;
   957      unsigned int count = chainCount;
   958      for (unsigned int i = 0; i < count; i++)
   959      {
   960        chain->apply (c);
   961        if (unlikely (!c->buffer->successful)) return;
   962        chain = &StructAfter<Chain> (*chain);
   963      }
   964    }
   965
   966    inline bool sanitize (hb_sanitize_context_t *c) const
   967    {
   968      TRACE_SANITIZE (this);
   969      if (!version.sanitize (c) || version < 2 ||
   970          !chainCount.sanitize (c))
   971        return_trace (false);
   972
   973      const Chain *chain = &firstChain;
   974      unsigned int count = chainCount;
   975      for (unsigned int i = 0; i < count; i++)
   976      {
   977        if (!chain->sanitize (c, version))
   978          return_trace (false);
   979        chain = &StructAfter<Chain> (*chain);
   980      }
   981
   982      return_trace (true);
   983    }
